const sample = {
  "demo": true,
  "email": "billing@brightline.example",
  "customer": "Brightline Studio",
  "amount": 149,
  "currency": "USD",
  "failedAt": "2026-11-22T08:00:00.000Z"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const failedAt = Date.parse(item.failedAt || item.created || new Date().toISOString());
const days = Math.floor((Date.now() - failedAt) / 86400000);
const steps = [0, 3, 7];
const step = steps.filter((value) => days >= value).pop();
const attempt = steps.indexOf(step) + 1;
const amount = Number(item.amount || 0);
const record = {
  customer: item.customer || item.email,
  email: item.email || '',
  amount,
  currency: item.currency || 'USD',
  days,
  attempt,
  subject: 'Payment attempt ' + attempt + ' for ' + amount + ' ' + (item.currency || 'USD'),
  body: 'The latest charge failed ' + days + ' days ago. Update the card to keep the workspace active.',
};
const route = attempt >= steps.length ? 'final' : 'retry';
return {
  summary: 'Dunning step ' + attempt + ' for ' + record.customer + ' (' + amount + ' ' + record.currency + ', ' + days + ' days).',
  route,
  record,
  slackText: route.toUpperCase() + ' dunning for ' + record.customer,
  actions: [{ app: 'email', operation: 'send', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'failed-payment-dunning',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
